2	 * Converts a readable stream into a Buffer.
3	 *
4	 * @param readableStream - The readable stream to convert.
5	 * @returns A promise that resolves to a Buffer containing the data from the stream.
6	 *
7	 * @example
8	 * ```typescript
9	 * import { streamToBuffer } from './utils';
10	 * import { createReadStream } from 'fs';
11	 *
12	 * const readableStream = createReadStream('path/to/file');
13	 * const buffer = await streamToBuffer(readableStream);
14	 * console.log(buffer.toString());
15	 * ```
16	 */
17	export async function streamToBuffer(
18	    readableStream: NodeJS.ReadableStream,
19	): Promise<Buffer> {
20	    return new Promise((resolve, reject) => {
21	        const chunks: Buffer[] = [];
22	        readableStream.on('data', (data: Buffer | Uint8Array) => {
23	            chunks.push(Buffer.isBuffer(data) ? data : Buffer.from(data));
24	        });
25	        readableStream.on('end', () => {
26	            resolve(Buffer.concat(chunks));
27	        });
28	        readableStream.on('error', reject);
29	    });
30	}
